import React, { useState, useEffect, useCallback } from 'react';
import Particles, { initParticlesEngine } from "@tsparticles/react";
import { loadSlim } from "@tsparticles/slim";
import * as faceapi from 'face-api.js';
import Navigation from './components/Navigation/Navigation.js';
import FaceRecognition from './components/FaceRecognition/FaceRecognition.js';
import Logo from './components/Logo/Logo.js';
import ImageLinkForm from './components/ImageLinkForm/ImageLinkForm.js';
import './App.css';

const particleOptions = {
  particles: {
    number: {
      value: 35,
      density: { enable: true, area: 900 }
    },
    color: { value: '#8b5cf6' },
    links: {
      enable: true,
      color: '#8b5cf6',
      opacity: 0.08,
      distance: 150
    },
    move: {
      enable: true,
      speed: 0.5,
      direction: "none",
      outModes: { default: "bounce" }
    },
    opacity: { value: 0.12 },
    size: { value: { min: 1, max: 2 } }
  },
  interactivity: {
    events: {
      onHover: { enable: true, mode: "grab" },
    },
    modes: {
      grab: { distance: 140, links: { opacity: 0.2 } }
    }
  }
};

const App = () => {
  const [input, setInput] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [detections, setDetections] = useState([]);
  const [particlesInit, setParticlesInit] = useState(false);
  const [modelsLoaded, setModelsLoaded] = useState(false);
  const [detecting, setDetecting] = useState(false);

  useEffect(() => {
    initParticlesEngine(async (engine) => {
      await loadSlim(engine);
    }).then(() => setParticlesInit(true));

    // Load all face detection models
    Promise.all([
      faceapi.nets.tinyFaceDetector.loadFromUri('/facerecognitionbrain/models'),
      faceapi.nets.faceLandmark68Net.loadFromUri('/facerecognitionbrain/models'),
      faceapi.nets.faceExpressionNet.loadFromUri('/facerecognitionbrain/models'),
      faceapi.nets.ageGenderNet.loadFromUri('/facerecognitionbrain/models'),
    ]).then(() => {
      console.log('✅ All face detection models loaded');
      setModelsLoaded(true);
    }).catch(err => console.log('Model load error:', err));
  }, []);

  const detectFaces = useCallback(async () => {
    const image = document.getElementById('inputimage');
    if (!image || !modelsLoaded) return;

    setDetecting(true);

    try {
      const results = await faceapi
        .detectAllFaces(image, new faceapi.TinyFaceDetectorOptions())
        .withFaceLandmarks()
        .withFaceExpressions()
        .withAgeAndGender();

      if (results.length > 0) {
        const displaySize = { width: image.width, height: image.height };
        const resizedResults = faceapi.resizeResults(results, displaySize);

        const faces = resizedResults.map(result => {
          const box = result.detection.box;
          const expressions = result.expressions;
          const topExpression = Object.entries(expressions)
            .sort((a, b) => b[1] - a[1])[0];

          return {
            box: {
              leftCol: box.x,
              topRow: box.y,
              width: box.width,
              height: box.height,
              rightCol: image.width - (box.x + box.width),
              bottomRow: image.height - (box.y + box.height)
            },
            age: Math.round(result.age),
            gender: result.gender,
            genderProbability: Math.round(result.genderProbability * 100),
            expression: topExpression[0],
            expressionScore: Math.round(topExpression[1] * 100)
          };
        });

        setDetections(faces);
      } else {
        setDetections([]);
      }
    } catch (err) {
      console.log('Detection error:', err);
      setDetections([]);
    }

    setDetecting(false);
  }, [modelsLoaded]);

  const onInputChange = (e) => setInput(e.target.value);

  const onButtonSubmit = () => {
    if (!input) return;
    setDetections([]);
    setDetecting(true);

    fetch(input)
      .then(res => res.blob())
      .then(blob => {
        const reader = new FileReader();
        reader.onloadend = () => {
          setImageUrl(reader.result);
          setDetecting(false);
        };
        reader.readAsDataURL(blob);
      })
      .catch(() => {
        setImageUrl(input);
        setDetecting(false);
      });
  };

  const onFileChange = (event) => {
    const file = event.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      setImageUrl(reader.result);
      setDetections([]);
    };
    reader.readAsDataURL(file);
  };

  const onImageLoaded = () => detectFaces();

  const onClear = () => {
    setImageUrl('');
    setDetections([]);
    setInput('');
  };

  return (
    <div className="App">
      {particlesInit && (
        <Particles id="tsparticles" className='particles' options={particleOptions} />
      )}
      <Navigation />
      <div className='main-content'>
        <Logo />

        <div className='hero-text'>
          <h1 className='hero-title'>AI Face Detection</h1>
          <p className='hero-subtitle'>
            Detect faces, estimate age, predict gender & read expressions — all in your browser.
          </p>
        </div>

        {!modelsLoaded && (
          <div className='models-loading'>
            <div className='models-loading-bar'></div>
            <span className='models-loading-text'>Loading AI models...</span>
          </div>
        )}

        <ImageLinkForm
          onInputChange={onInputChange}
          onButtonSubmit={onButtonSubmit}
          onFileChange={onFileChange}
          onClear={onClear}
          hasImage={!!imageUrl}
        />

        {detecting && (
          <div className='detecting-indicator'>
            <div className='detecting-spinner'></div>
            <span className='detecting-text'>Analyzing faces...</span>
          </div>
        )}

        {detections.length > 0 && !detecting && (
          <div className='results-summary'>
            <span className='results-count'>{detections.length} face{detections.length > 1 ? 's' : ''} detected</span>
          </div>
        )}

        <FaceRecognition
          detections={detections}
          imageUrl={imageUrl}
          onImageLoaded={onImageLoaded}
        />
      </div>
    </div>
  );
};

export default App;
